// Loads only the fixed scalar credential schema generated by up.sh. It runs
// supported real browser scenarios without exporting or printing credentials.
// The test passwords are relayed to Playwright's process environment only;
// they are never persisted in a browser report or a second local file.
// This legacy harness is not the auth/audit acceptance gate; the recorded
// auth/audit acceptance uses direct browser interaction against Kubernetes.

import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";

const file = process.env.QUOIN_E2E_CREDENTIALS_FILE;
if (!file) throw new Error("QUOIN_E2E_CREDENTIALS_FILE is required");
const values = Object.fromEntries(
	readFileSync(file, "utf8")
		.split("\n")
		.flatMap((line) => {
			const match = /^([a-zA-Z]+): (.+)$/.exec(line.trim());
			return match ? [[match[1], match[2]]] : [];
		}),
);
for (const key of [
	"url",
	"username",
	"initialPassword",
	"finalPassword",
	"contactEmail",
	"smtpPassword",
	"otpRecordFile",
]) {
	if (!values[key]) throw new Error(`generated credentials.yaml lacks ${key}`);
}
const repoRoot = new URL("../../", import.meta.url).pathname;

const playwrightArgs = ["--dir", "web", "test:e2e:real"];
// A focused issue suite is still run through the same private credential loader
// and real stack; this prevents #97 from relying on #102's ordering side effect.
if (process.env.QUOIN_E2E_PLAYWRIGHT_FILE)
	playwrightArgs.push(process.env.QUOIN_E2E_PLAYWRIGHT_FILE);
const result = spawnSync("pnpm", playwrightArgs, {
	cwd: repoRoot,
	stdio: "inherit",
	env: {
		...process.env,
		QUOIN_REAL_E2E_BASE_URL: values.url,
		QUOIN_E2E_ADMIN_USERNAME: values.username,
		QUOIN_E2E_ADMIN_INITIAL_PASSWORD: values.initialPassword,
		QUOIN_E2E_ADMIN_FINAL_PASSWORD: values.finalPassword,
		QUOIN_E2E_RUNTIME: process.env.QUOIN_E2E_RUNTIME,
		QUOIN_E2E_PORT: process.env.QUOIN_E2E_PORT,
		QUOIN_E2E_PROJECT: process.env.QUOIN_E2E_PROJECT,
	},
});
process.exit(result.status ?? 1);
